using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class B3Finish {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B3_FullFloor/";const string A="Assets/Afrer_Seconds/05.Model/",E=A+"Environment/B3/";
 static Scene Check(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B3_Circular.unity"))throw new Exception("Saved B3 required");return s;}
 public static object CCTV(){var s=Check();AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var mats=AssetDatabase.FindAssets("t:Material",new[]{E+"Materials"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<Material>).ToArray();foreach(string f in Directory.GetFiles(E,"BS_CCTVWallMount_*.fbx")){var mi=(ModelImporter)AssetImporter.GetAtPath(f.Replace('\\','/'));mi.importAnimation=false;mi.isReadable=true;mi.importNormals=ModelImporterNormals.Import;mi.importTangents=ModelImporterTangents.CalculateMikk;foreach(var m in mats.Where(m=>m.name.StartsWith("B3M_")))mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"B4O_"+m.name.Substring(5)),m);mi.SaveAndReimport();}var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B3_"));int n=0;foreach(var r in JObject.Parse(File.ReadAllText(H+"layout.json"))["rooms"].Where(r=>(string)r["kind"]!="core")){string id=(string)r["id"];var parent=root.transform.Find("B3_"+id+"_Sector/Equipment");if(parent.Find("B3_"+id+"_CCTV"))throw new Exception("CCTV already added");float rad=(float)r["r"],ang=(float)r["doors"][0]["angle"]+Mathf.Asin(3.0f/rad)*Mathf.Rad2Deg+12;var dir=new Vector3(Mathf.Cos(ang*Mathf.Deg2Rad),0,Mathf.Sin(ang*Mathf.Deg2Rad));float face=Mathf.Sqrt(rad*rad-3.65f*3.65f)-.16f;var mount=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(E+"BS_CCTVWallMount_R"+((int)rad)+".fbx"),parent);mount.name="B3_"+id+"_CCTVWallMount";mount.transform.localPosition=dir*face;mount.transform.localRotation=Quaternion.LookRotation(-dir);var camera=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(A+"Enemy/CCTV_SecurityCamera_Articulated.prefab"),parent);camera.name="B3_"+id+"_CCTV";camera.transform.SetPositionAndRotation(mount.transform.TransformPoint(new Vector3(0,3.287f,.49f)),mount.transform.rotation);foreach(var t in new[]{mount.transform,camera.transform})PrefabUtility.RecordPrefabInstancePropertyModifications(t);n++;}EditorSceneManager.MarkSceneDirty(s);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(s);return new{cameras=n,motorScriptsAdded=0};}
 public static object Reflections(){var s=Check();var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var parent=new GameObject("B3_StaticReflections");bool active=player.activeSelf;player.SetActive(false);int count=0;try{foreach(var r in JObject.Parse(File.ReadAllText(H+"layout.json"))["rooms"]){float rad=(float)r["r"];var g=new GameObject("Reflection_"+(string)r["id"]);g.transform.SetParent(parent.transform);g.transform.position=new Vector3((float)r["x"],-47.0f,-(float)r["v"]);var p=g.AddComponent<ReflectionProbe>();p.size=new Vector3(rad*2,rad+2,rad*2);p.center=new Vector3(0,rad*.5f-2,0);p.blendDistance=1;p.resolution=128;p.hdr=true;p.boxProjection=true;p.mode=ReflectionProbeMode.Custom;p.renderDynamicObjects=true;p.clearFlags=ReflectionProbeClearFlags.SolidColor;p.backgroundColor=new Color(.025f,.030f,.035f);p.intensity=.8f;string file=E+"Textures/BS_Reflection_"+(string)r["id"]+".exr";if(!Lightmapping.BakeReflectionProbe(p,file))throw new Exception("Probe failed");AssetDatabase.ImportAsset(file,ImportAssetOptions.ForceSynchronousImport);p.customBakedTexture=AssetDatabase.LoadAssetAtPath<Cubemap>(file);count++;}}finally{player.SetActive(active);}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{probes=count};}
 public static object Lods(){var s=Check();var old=JArray.Parse(File.ReadAllText(R+"/SourceAssets/B4_Finish/lod_plan.json"));var rs=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>()).Where(r=>r.GetComponent<MeshFilter>()&&r.GetComponent<MeshFilter>().sharedMesh).ToArray();var fresh=new List<object>();var reuse=new List<JObject>();foreach(var group in rs.GroupBy(r=>r.GetComponent<MeshFilter>().sharedMesh)){var m=group.Key;string path=AssetDatabase.GetAssetPath(m);int tri=m.triangles.Length/3;if(!(path.Contains("/Props/")&&tri>=9000||path.Contains("CFD_TunnelRib")||path.EndsWith("BO_SealedTaskLight.fbx")))continue;var previous=old.FirstOrDefault(p=>(string)p["asset"]==path&&(string)p["mesh"]==m.name);var ids=group.Select(r=>GlobalObjectId.GetGlobalObjectIdSlow(r).ToString()).ToArray();if(previous!=null){var q=(JObject)previous.DeepClone();q["renderers"]=JArray.FromObject(ids);q["instances"]=ids.Length;reuse.Add(q);}else fresh.Add(new{asset=path,mesh=m.name,tri,instances=ids.Length,materials=group.First().sharedMaterials.Select(AssetDatabase.GetAssetPath).ToArray(),name="BL_"+Path.GetFileNameWithoutExtension(path),renderers=ids});}File.WriteAllText(H+"lod_plan.json",JsonConvert.SerializeObject(fresh,Formatting.Indented));File.WriteAllText(H+"lod_reuse.json",JsonConvert.SerializeObject(reuse,Formatting.Indented));return new{newMeshes=fresh.Count,reusedMeshes=reuse.Count,newInstances=fresh.Sum(x=>(int)x.GetType().GetProperty("instances").GetValue(x)),reusedInstances=reuse.Sum(x=>(int)x["instances"])};}
 public static object Audit(){var s=Check();var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var rs=all.SelectMany(t=>t.GetComponents<MeshRenderer>()).ToArray();var mfs=all.SelectMany(t=>t.GetComponents<MeshFilter>()).ToArray();var bad=new List<object>();foreach(var m in mfs.Where(f=>f.sharedMesh).Select(f=>f.sharedMesh).Distinct()){if(!m.isReadable)continue;var v=m.vertices;var ix=m.triangles;int degen=0;for(int i=0;i<ix.Length;i+=3)if(Vector3.Cross(v[ix[i+1]]-v[ix[i]],v[ix[i+2]]-v[ix[i]]).sqrMagnitude<1e-16f)degen++;if(degen>0)bad.Add(new{name=m.name,degen});}var result=new{scene=s.path,saved=!s.isDirty,objects=all.Length,renderers=rs.Length,missingMeshes=mfs.Count(m=>!m.sharedMesh),missingMaterials=rs.Sum(r=>r.sharedMaterials.Count(m=>!m)),nonAscii=all.Count(t=>t.name.Any(c=>c>127)),lights=all.Sum(t=>t.GetComponents<Light>().Length),enabledLights=all.Sum(t=>t.GetComponents<Light>().Count(l=>l.enabled)),cctvs=all.Count(t=>t.name.EndsWith("_CCTV")),colliders=all.Sum(t=>t.GetComponents<Collider>().Length),lodGroups=all.Sum(t=>t.GetComponents<LODGroup>().Length),probes=all.Sum(t=>t.GetComponents<ReflectionProbe>().Length),meshIssues=bad};File.WriteAllText(R+"/Docs/Review/2026-11-09_B3_FullFloor/audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
